// 1. Obtener el stdout de SSH que contiene el JSONL del transcript
const logContent = $input.item.json.stdout || '';

// Dividir por líneas y recorrer en reversa
const lines = logContent.trim().split('\n').reverse();

let lastResponse = '';
for (const line of lines) {
  try {
    const data = JSON.parse(line);
    if (data.source === 'MODEL' && data.type === 'PLANNER_RESPONSE' && data.content && data.content.trim()) {
      lastResponse = data.content;
      break;
    }
  } catch (e) {
    // Ignorar
  }
}

if (!lastResponse) {
  return [{
    json: {
      stdout_clean: "No se encontró respuesta en la sesión activa."
    }
  }];
}

// 2. Convertir Markdown a formato nativo de WhatsApp
function markdownToWhatsApp(text) {
  let processedText = text;

  // A. Convertir listas HTML que pudieran venir del modelo
  processedText = processedText.replace(/<ol[^>]*>([\s\S]*?)<\/ol>/gi, (match, listContent) => {
    let index = 1;
    return listContent.replace(/<li[^>]*>([\s\S]*?)<\/li>\s*\n?/gi, (liMatch, itemContent) => {
      return `${index++}. ${itemContent.trim()}\n`;
    });
  });

  processedText = processedText.replace(/<ul[^>]*>([\s\S]*?)<\/ul>/gi, (match, listContent) => {
    return listContent.replace(/<li[^>]*>([\s\S]*?)<\/li>\s*\n?/gi, (liMatch, itemContent) => {
      return `- ${itemContent.trim()}\n`;
    });
  });

  processedText = processedText.replace(/<li[^>]*>([\s\S]*?)<\/li>\s*\n?/gi, (match, itemContent) => {
    return `- ${itemContent.trim()}\n`;
  });

  // B. Limpiar tags HTML comunes convirtiéndolos a texto plano de WhatsApp
  processedText = processedText
    .replace(/<\/?(?:b|strong)>/gi, '*')
    .replace(/<\/?(?:i|em)>/gi, '_')
    .replace(/<\/?code>/gi, '`')
    .replace(/<\/?pre[^>]*>/gi, '```')
    .replace(/<h[1-6][^>]*>([\s\S]*?)<\/h[1-6]>/gi, '*$1*\n')
    .replace(/<p[^>]*>([\s\S]*?)<\/p>\s*\n?/gi, '$1\n\n')
    .replace(/<div[^>]*>([\s\S]*?)<\/div>\s*\n?/gi, '$1\n')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>');

  // C. Eliminar cualquier otro tag HTML residual
  processedText = processedText.replace(/<[^>]*>/g, '');

  // D. Convertir Markdown a Marcado de WhatsApp
  processedText = processedText.replace(/```(?:[a-zA-Z0-9_+#-]+)?\n([\s\S]*?)\n```/g, '```\n$1\n```');

  // Convertir negritas a temporal
  processedText = processedText.replace(/\*\*([^*]+)\*\*/g, '⦃B⦄$1⦃/B⦄');
  processedText = processedText.replace(/__([^_]+)__/g, '⦃B⦄$1⦃/B⦄');

  // Convertir itálicas (asterisco simple) a guion bajo
  processedText = processedText.replace(/\*([^*]+)\*/g, '_$1_');

  // Restaurar negritas temporales a asterisco de WhatsApp
  processedText = processedText.replace(/⦃B⦄/g, '*').replace(/⦃\/B⦄/g, '*');

  processedText = processedText.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '$1 ($2)');
  processedText = processedText.replace(/^(?:#{1,6})\s+(.+)$/gm, '*$1*');

  return processedText.trim();
}

function chunkString(str, limit) {
  const chunks = [];
  let index = 0;
  while (index < str.length) {
    if (str.length - index <= limit) {
      chunks.push(str.substring(index));
      break;
    }
    let cutPos = str.lastIndexOf('\n', index + limit);
    if (cutPos <= index) {
      cutPos = str.lastIndexOf(' ', index + limit);
    }
    if (cutPos <= index) {
      cutPos = index + limit;
    }
    chunks.push(str.substring(index, cutPos));
    index = cutPos + 1;
  }
  return chunks;
}

const CHAR_LIMIT = 4000;
const chunks = chunkString(lastResponse, CHAR_LIMIT);

return chunks.map(chunk => ({
  json: {
    stdout_clean: markdownToWhatsApp(chunk)
  }
}));
